"use strict";

// Every computed-key FORM the language offers, in one module. All of them
// are evaluated by ClassDefinitionEvaluation; none of the method,
// getter or setter BODIES are.
//
// Before RWF-023 the four element kinds split into two groups for a
// reason that had nothing to do with the language: a field and an
// accessor are not function-like, so the call-graph walk never made them
// the owner and their keys were already attributed to the module; a
// METHOD is function-like, so the walk pushed the method's own node
// before descending into its name and the key's calls landed in a
// deferred region. `async` and generator methods, and static methods, are
// all MethodDeclarations too, which is why all four were lost together.
const danger = require("./danger");

function instanceFieldKey() {
  danger.explode("instance-field-key");
  return "a";
}
function staticFieldKey() {
  danger.explode("static-field-key");
  return "b";
}
function instanceMethodKey() {
  danger.explode("instance-method-key");
  return "c";
}
function staticMethodKey() {
  danger.explode("static-method-key");
  return "d";
}
function getterKey() {
  danger.explode("getter-key");
  return "e";
}
function setterKey() {
  danger.explode("setter-key");
  return "f";
}
function asyncMethodKey() {
  danger.explode("async-method-key");
  return "g";
}
function generatorMethodKey() {
  danger.explode("generator-method-key");
  return "h";
}

class AllForms {
  [instanceFieldKey()] = 1;
  static [staticFieldKey()] = 2;
  [instanceMethodKey()]() {}
  static [staticMethodKey()]() {}
  get [getterKey()]() {
    return 3;
  }
  set [setterKey()](v) {}
  async [asyncMethodKey()]() {}
  *[generatorMethodKey()]() {}
}

module.exports = AllForms;
